SELECT 'PASS explicit privileges and original association backfill';
CREATE TABLE fixture_extras_ids(name text PRIMARY KEY,id uuid);
DO $$
DECLARE b uuid:='00000000-0000-0000-0000-00000000e001'; original uuid:='00000000-0000-0000-0000-00000000e002'; batch uuid:='00000000-0000-0000-0000-00000000e003'; batch2 uuid:='00000000-0000-0000-0000-00000000e004'; inv uuid; inv2 uuid; result jsonb;
BEGIN
 INSERT INTO private_bookings(id,customer_name,event_date,start_time,status) VALUES(b,'Fixture extra booking',CURRENT_DATE+30,'18:00','confirmed');
 INSERT INTO private_booking_items(booking_id,item_type,description,quantity,unit_price,vat_rate) VALUES(b,'other','Original hire',1,100,20);
 INSERT INTO invoices(id,invoice_number,vendor_id,invoice_date,due_date,subtotal_amount,vat_amount,total_amount,status) VALUES(original,'FIXTURE-EXTRAS',gen_random_uuid(),CURRENT_DATE,CURRENT_DATE+30,100,20,120,'draft');
 UPDATE private_bookings SET invoice_id=original,invoice_deposit_treatment='held_separately' WHERE id=b;
 PERFORM record_invoice_paypal_payment_atomic(original,120,'EXTRAS-ORIGINAL-PAID',NULL,now());
 PERFORM fixture_assert((SELECT final_payment_date IS NOT NULL FROM private_bookings WHERE id=b),'original settled');
 PERFORM save_private_booking_charge_batch(b,batch,0,'[{"description":"Evening food","quantity":2,"unit_price":10,"vat_rate":20,"discount_percentage":0}]',CURRENT_DATE+20,'Extras',NULL);
 PERFORM fixture_assert(calculate_private_booking_balance(b)=0,'draft excluded from balance');
 PERFORM fixture_assert(get_private_booking_aggregate_gross_total(b)=120,'draft excluded from charges');
 result:=issue_private_booking_charge_batch(b,batch,1,NULL); inv:=(result->'invoice'->>'id')::uuid;
 INSERT INTO fixture_extras_ids VALUES('booking',b),('original',original),('batch',batch),('supplement',inv);
 PERFORM fixture_assert(calculate_private_booking_balance(b)=24,'issued extras reopen balance');
 PERFORM fixture_assert((SELECT final_payment_date IS NULL FROM private_bookings WHERE id=b),'paid stamp cleared');
 PERFORM fixture_assert((SELECT total_amount=120 AND paid_amount=120 FROM invoices WHERE id=original),'original unchanged');
 PERFORM fixture_assert((issue_private_booking_charge_batch(b,batch,1,NULL)->>'created')::boolean=false,'issue retry idempotent');
 PERFORM fixture_throws(format('UPDATE invoice_line_items SET description=%L WHERE invoice_id=%L','Changed',inv),'Resolve the linked invoice');
 PERFORM fixture_throws(format('UPDATE invoices SET total_amount=25 WHERE id=%L',inv),'Resolve the linked invoice');
 PERFORM fixture_throws(format('SELECT cancel_private_booking_invoice_atomic(%L,%L,NULL)',b,'Cancel original'),'invoice_has_real_payments');
 PERFORM fixture_throws(format('SELECT record_balance_payment(%L,1,%L)',b,'cash'),'Select invoice allocations');
 PERFORM fixture_throws(format('INSERT INTO invoice_payments(invoice_id,payment_date,amount,payment_method,source_kind) VALUES(%L,CURRENT_DATE,1,%L,%L)',inv,'cash','booking_deposit'),'Deposits cannot be applied again');
 PERFORM save_private_booking_charge_batch(b,batch2,0,'[{"description":"Late finish","quantity":1,"unit_price":10,"vat_rate":0}]',CURRENT_DATE+20,NULL,NULL);
 result:=issue_private_booking_charge_batch(b,batch2,1,NULL);inv2:=(result->'invoice'->>'id')::uuid;
 INSERT INTO fixture_extras_ids VALUES('supplement2',inv2),('batch2',batch2);
 PERFORM record_private_booking_allocated_payment(b,'00000000-0000-0000-0000-00000000e010',CURRENT_DATE,14,'cash','SPLIT',NULL,jsonb_build_array(jsonb_build_object('invoice_id',inv,'amount',10),jsonb_build_object('invoice_id',inv2,'amount',4)),NULL);
 PERFORM fixture_assert(calculate_private_booking_balance(b)=20,'split receipt allocated correctly');
 PERFORM fixture_assert((SELECT sum(amount)=14 AND count(*)=2 FROM invoice_payments WHERE receipt_id='00000000-0000-0000-0000-00000000e010'),'two allocations one receipt');
 PERFORM record_private_booking_allocated_payment(b,'00000000-0000-0000-0000-00000000e010',CURRENT_DATE,14,'cash','SPLIT',NULL,jsonb_build_array(jsonb_build_object('invoice_id',inv,'amount',10),jsonb_build_object('invoice_id',inv2,'amount',4)),NULL);
 PERFORM fixture_assert((SELECT count(*)=2 FROM invoice_payments WHERE receipt_id='00000000-0000-0000-0000-00000000e010'),'receipt retry idempotent');
 PERFORM fixture_throws(format('SELECT cancel_private_booking_charge_batch(%L,%L,%L,NULL)',b,batch2,'Cancel'),'invoice_has_real_payments');
 INSERT INTO credit_notes(credit_note_number,invoice_id,vendor_id,amount_ex_vat,vat_rate,amount_inc_vat,reason,status,created_by) VALUES('FIXTURE-CREDIT',inv2,gen_random_uuid(),6,0,6,'Unused late finish','issued',gen_random_uuid());
 PERFORM fixture_assert(calculate_private_booking_balance(b)=14,'issued credit reduces balance');
 PERFORM record_invoice_paypal_payment_atomic(inv,14,'EXTRAS-PAID',NULL,now());
 PERFORM record_invoice_paypal_payment_atomic(inv,14,'EXTRAS-PAID',NULL,now());
 PERFORM fixture_assert(calculate_private_booking_balance(b)=0,'all invoices settled after credit and capture');
 PERFORM fixture_assert((SELECT final_payment_date IS NOT NULL FROM private_bookings WHERE id=b),'paid stamp restored');
 PERFORM fixture_assert((SELECT count(*)=1 FROM invoice_payments WHERE reference='EXTRAS-PAID'),'capture deduplicated');
 PERFORM fixture_assert(get_private_booking_settlement_total(b)=148,'deposit copies and split allocations not double counted');
END $$;
SELECT 'PASS issue retries, original immutability, draft exclusion, split allocations, credits, captures, paid stamps';
DO $$
DECLARE b uuid:=(SELECT id FROM fixture_extras_ids WHERE name='booking');d uuid:='00000000-0000-0000-0000-00000000e020';i uuid;
BEGIN
 PERFORM save_private_booking_charge_batch(b,d,0,'[{"description":"Unused extra","quantity":1,"unit_price":5,"vat_rate":20}]',CURRENT_DATE+20,NULL,NULL);
 i:=(issue_private_booking_charge_batch(b,d,1,NULL)->'invoice'->>'id')::uuid;
 UPDATE invoices SET paypal_order_id='PENDING-ORDER' WHERE id=i;
 PERFORM fixture_throws(format('SELECT cancel_private_booking_charge_batch(%L,%L,%L,NULL)',b,d,'Not required'),'Resolve the pending PayPal order');
 UPDATE invoices SET paypal_order_id=NULL WHERE id=i;
 PERFORM cancel_private_booking_charge_batch(b,d,'Not required',NULL);
 PERFORM fixture_assert((SELECT status='void' FROM invoices WHERE id=i),'cancel voids invoice');
 PERFORM fixture_assert(calculate_private_booking_balance(b)=0,'cancel removes collectible balance');
 PERFORM fixture_throws(format('SELECT record_invoice_paypal_payment_atomic(%L,6,%L)',i,'VOID-CAPTURE'),'invoice_not_payable');
 PERFORM fixture_assert(reserve_private_booking_receipt_version(b)=1,'receipt version one');
 PERFORM fixture_assert(reserve_private_booking_receipt_version(b)=2,'receipt version increments');
 INSERT INTO private_booking_documents(booking_id,document_type,file_name,storage_path,version) VALUES(b,'receipt','historic.pdf','fixture/historic.pdf',10);
 PERFORM fixture_assert(reserve_private_booking_receipt_version(b)=11,'historic receipt versions respected');
END $$;
