BEGIN
 PERFORM save_private_booking_charge_batch(b,d,0,'[{"description":"Fractional one","quantity":0.333,"unit_price":0.10,"vat_rate":20,"discount_percentage":10},{"description":"Fractional two","quantity":0.333,"unit_price":0.10,"vat_rate":20,"discount_percentage":10}]',CURRENT_DATE+20,NULL,NULL);
 result:=issue_private_booking_charge_batch(b,d,1,NULL);i:=(result->'invoice'->>'id')::uuid;
