 PERFORM fixture_throws(format('SELECT save_private_booking_charge_batch(%L,%L,0,%L::jsonb,CURRENT_DATE+1,NULL,NULL)',b,gen_random_uuid(),'[{"description":"Precision","quantity":0.3333,"unit_price":1,"vat_rate":20}]'),'invalid_extra_line');
 PERFORM fixture_throws(format('SELECT record_private_booking_allocated_payment(%L,%L,CURRENT_DATE,1,%L,NULL,NULL,%L::jsonb,NULL)',b,gen_random_uuid(),'cash',jsonb_build_array(jsonb_build_object('invoice_id',i,'amount',1))),'allocation_exceeds_invoice_balance');
 PERFORM fixture_assert((SELECT count(*)=1 FROM private_booking_payment_receipts),'failed allocations rolled back receipt');
 PERFORM cancel_private_booking_charge_batch(b,d,'Rounding fixture complete',NULL);
END $$;
