DO $$
DECLARE b uuid:='00000000-0000-0000-0000-00000000e051'; i uuid:='00000000-0000-0000-0000-00000000e052'; d uuid:='00000000-0000-0000-0000-00000000e053'; extra uuid;
BEGIN
 INSERT INTO private_bookings(id,customer_name,event_date,start_time,status,deposit_amount,deposit_paid_date) VALUES(b,'Deposit fixture',CURRENT_DATE+30,'18:00','confirmed',20,now());
 INSERT INTO private_booking_items(booking_id,item_type,description,quantity,unit_price,vat_rate) VALUES(b,'other','Original hire',1,100,20);
 INSERT INTO private_booking_payments(booking_id,amount,method) VALUES(b,10,'cash');
 INSERT INTO invoices(id,invoice_number,vendor_id,invoice_date,due_date,subtotal_amount,vat_amount,total_amount,status) VALUES(i,'FIXTURE-DEPOSIT',gen_random_uuid(),CURRENT_DATE,CURRENT_DATE+30,100,20,120,'draft');
 INSERT INTO invoice_payments(invoice_id,amount,payment_date,payment_method,source_kind,source_payment_id,notes) SELECT i,amount,(created_at AT TIME ZONE 'Europe/London')::date,'cash','booking_payment',id,notes FROM private_booking_payments WHERE booking_id=b;
 UPDATE private_bookings SET invoice_id=i,invoice_deposit_treatment='deducted' WHERE id=b;
 INSERT INTO invoice_payments(invoice_id,amount,payment_date,payment_method,source_kind) VALUES(i,20,CURRENT_DATE,'cash','booking_deposit');
 PERFORM fixture_assert(calculate_private_booking_balance(b)=90,'legacy cash mirrored plus deducted deposit counted once');
 PERFORM save_private_booking_charge_batch(b,d,0,'[{"description":"Extra","quantity":1,"unit_price":5,"vat_rate":20}]',CURRENT_DATE+20,NULL,NULL);
 extra:=(issue_private_booking_charge_batch(b,d,1,NULL)->'invoice'->>'id')::uuid;
 PERFORM fixture_assert(calculate_private_booking_balance(b)=96,'deducted deposit not applied twice');
 PERFORM fixture_assert(get_private_booking_settlement_total(b)=30,'single deposit plus legacy cash');
 PERFORM record_invoice_paypal_payment_atomic(i,100,'OVERPAID-ORIGINAL',NULL,now());
 PERFORM fixture_assert(calculate_private_booking_balance(b)=6,'original overpayment cannot hide extra balance');
 PERFORM fixture_assert((SELECT final_payment_date IS NULL FROM private_bookings WHERE id=b),'overpaid original does not mark whole booking paid');
END $$;
