DO $$
DECLARE b uuid:=(SELECT id FROM fixture_extras_ids WHERE name='booking');i uuid:=(SELECT id FROM fixture_extras_ids WHERE name='supplement');c jsonb;
BEGIN
 PERFORM fixture_throws(format('UPDATE invoices SET status=%L WHERE id=%L','written_off',i),'Cancel the invoice from its private booking');
 c:=claim_private_booking_extra_delivery(b,i,NULL,false);
 PERFORM fixture_assert((c->>'claimed')::boolean,'first delivery claimed');
 PERFORM fixture_assert((claim_private_booking_extra_delivery(b,i,NULL,false)->>'claimed')::boolean=false,'second sender cannot claim');
 PERFORM fixture_assert((claim_private_booking_extra_delivery(b,i,NULL,true)->>'claimed')::boolean=false,'explicit resend cannot steal pending claim');
 PERFORM fixture_throws(format('SELECT finish_private_booking_extra_delivery(%L,%L,%L,true,NULL)',b,i,gen_random_uuid()),'delivery_claim_conflict');
 PERFORM finish_private_booking_extra_delivery(b,i,(c->>'claim_id')::uuid,false,'Fixture delivery failed');
 PERFORM fixture_assert((claim_private_booking_extra_delivery(b,i,NULL,false)->>'claimed')::boolean=false,'failed send only retried explicitly');
 c:=claim_private_booking_extra_delivery(b,i,NULL,true);
 PERFORM fixture_assert((c->>'claimed')::boolean,'explicit resend can retry failure');
 PERFORM finish_private_booking_extra_delivery(b,i,(c->>'claim_id')::uuid,true,NULL);
 PERFORM fixture_assert((claim_private_booking_extra_delivery(b,i,NULL,false)->>'claimed')::boolean=false,'issued retry cannot resend delivered invoice');
END $$;
