DO $$
DECLARE before_stats record;after_stats record;i uuid:='00000000-0000-0000-0000-00000000e090';
BEGIN
 SELECT * INTO before_stats FROM get_invoice_summary_stats();
 INSERT INTO invoices(id,invoice_number,vendor_id,invoice_date,due_date,subtotal_amount,vat_amount,total_amount,status,sent_at) VALUES(i,'FIXTURE-SUMMARY',gen_random_uuid(),CURRENT_DATE,CURRENT_DATE-1,100,20,120,'overdue',now());
 INSERT INTO credit_notes(credit_note_number,invoice_id,vendor_id,amount_ex_vat,vat_rate,amount_inc_vat,reason,status,created_by) VALUES('SUMMARY-CREDIT',i,gen_random_uuid(),50,20,60,'Reduced charge','issued',gen_random_uuid());
 INSERT INTO invoice_payments(invoice_id,amount,payment_date,payment_method) VALUES(i,10,CURRENT_DATE,'cash');
 -- Partially paid invoice status is normal; mark overdue to exercise dashboard overdue metric.
 UPDATE invoices SET status='overdue' WHERE id=i;
 SELECT * INTO after_stats FROM get_invoice_summary_stats();
 PERFORM fixture_assert(after_stats.total_outstanding-before_stats.total_outstanding=50,'summary deducts credits and cash once');
 PERFORM fixture_assert(after_stats.total_overdue-before_stats.total_overdue=50,'overdue summary deducts credits');
 PERFORM fixture_assert(after_stats.total_this_month=before_stats.total_this_month,'monthly paid charges unchanged for unpaid invoice');
END $$;
